use crossterm::event::{KeyEvent, MouseEvent};
use uuid::Uuid;

use crate::acp::ToolCallUpdateSummary;
use crate::model::message::{ContentPart, TokenUsage, ToolCallInfo};
use crate::pricing::PricingCatalog;
use crate::tools::PermissionLevel;

/// Events generated by the terminal event loop and dispatched to the application.
#[derive(Clone, Debug)]
#[allow(dead_code)]
pub enum Event {
    /// Application initialized
    Init,
    /// Application should quit
    Quit,
    /// An error occurred in the event loop
    Error,
    /// Periodic tick for background logic
    Tick,
    /// Time to render a frame
    Render,
    /// Terminal gained focus
    FocusGained,
    /// Terminal lost focus
    FocusLost,
    /// Paste event (bracketed paste)
    Paste(String),
    /// Key press event
    Key(KeyEvent),
    /// Mouse event
    Mouse(MouseEvent),
    /// Terminal resized
    Resize(u16, u16),

    // -- Streaming events (injected by provider bridge task) --
    /// A chunk of text arrived from the LLM stream
    StreamChunk(String),
    /// The LLM stream completed successfully (no tool calls)
    StreamDone { usage: Option<TokenUsage> },
    /// The LLM stream completed with tool calls
    StreamDoneWithToolCalls {
        tool_calls: Vec<ToolCallInfo>,
        usage: Option<TokenUsage>,
    },
    /// An error occurred during LLM streaming
    StreamError(String),

    // -- Tool events --
    /// A tool finished executing
    ToolExecutionResult {
        call_id: String,
        fn_name: String,
        content: Vec<ContentPart>,
        success: bool,
        /// Binary blobs from MCP image responses: (id, mime_type, data).
        /// Empty for built-in tools.
        blobs: Vec<(Uuid, String, Vec<u8>)>,
    },

    // -- Compaction events --
    /// Compaction completed: Ok((summary, compacted_ids, usage)) or Err(error_message)
    CompactionResult(std::result::Result<(String, Vec<Uuid>, Option<TokenUsage>), String>),

    // -- Title generation events --
    /// LLM-generated title for the conversation
    TitleGenerated(std::result::Result<(String, Option<TokenUsage>), String>),

    // -- Pricing events --
    /// Pricing catalog loaded from models.dev
    PricingLoaded(PricingCatalog),

    // -- Model discovery events --
    /// A provider's model list finished loading. Contains (provider_name, models).
    ProviderModelsFetched(String, Vec<String>),

    // -- ACP events --
    /// Agent requested permission for a tool operation.
    AcpPermissionRequest {
        request_id: String,
        call_id: String,
        tool_name: String,
        permission_level: PermissionLevel,
    },
    /// Tool call announced by the ACP agent (for display).
    AcpToolCall(ToolCallInfo),
    /// Tool call progress/result update from the ACP agent.
    AcpToolCallUpdate(ToolCallUpdateSummary),
    /// User message chunk during ACP session/load replay.
    AcpUserMessageChunk(String),
    /// Session title update from the agent.
    AcpSessionTitle(String),
    /// Usage/context update from the agent.
    AcpUsageUpdate(TokenUsage),
    /// ACP session/load finished replaying history.
    AcpSessionLoadComplete,
}
